/** schema name (its path in hypermedia/) -> the name and summary of the page that defines it. */
// prettier-ignore
export const HM_SCHEMA_PAGES: Record<string, {name: string; summary?: string}> = {"account":{"name":"Account","summary":"A reference to an account, held as the bare `hm://<principal>` URL, with `format: hm-profile` so editors offer an account search and accept a pasted principal."},"any":{"name":"Any","summary":"The top type that matches any Hypermedia value: null, boolean, number, string, bytes, link, or a list or map of any."},"blob":{"name":"Blob","summary":"The signed envelope every Hypermedia blob extends, with a type tag, the signer's public key, an Ed25519 signature over the canonical CBOR with the signature zeroed, and a millisecond timestamp."},"blob/any":{"name":"Any Blob","summary":"Any Hypermedia CBOR blob: the discriminated union of the six blob types, tagged on the type field."},"block":{"name":"Block","summary":"The open wire block: id and type plus text, link, annotations and any attributes, so a document with a block type you do not know still parses."},"block/annotation":{"name":"Annotation","summary":"An inline layer over a block's text: a type, one or more code-point ranges, an optional link and inline attributes, used for formatting, links and mentions."},"block/base":{"name":"Block (Base)","summary":"The three fields every concrete block type shares: the required id and type, and the daemon-filled revision."},"block/button-alignment":{"name":"Button Alignment","summary":"The horizontal alignment of a Button block: flex-start, center or flex-end."},"block/button":{"name":"Button Block","summary":"A call-to-action button: a label, a required link and a horizontal alignment."},"block/children-type":{"name":"Children Type","summary":"How a block lays out its children: Group (the default), Ordered, Unordered, Blockquote or Grid."},"block/code":{"name":"Code Block","summary":"A block of verbatim text, optionally tagged with a programming language for highlighting."},"block/comment":{"name":"Comment Block","summary":"A block inside a comment body: the open block plus a recursive list of child comment blocks."},"block/core":{"name":"Core Block","summary":"The strict union of the fifteen built-in block types; extend it with your own types by making a larger union that includes it."},"block/embed-view":{"name":"Embed View","summary":"How an Embed block renders its target: the content itself, a card, its discussion, or a plain link."},"block/embed":{"name":"Embed Block","summary":"An embed of another Hypermedia document, block or text range by hm:// link, rendered as content, a card, its comments or a link."},"block/file":{"name":"File Block","summary":"An attachment of any kind, referenced by an ipfs:// link, with its file name and size."},"block/heading":{"name":"Heading Block","summary":"A section heading whose children are the section; the heading level comes from nesting, not from an attribute."},"block/image":{"name":"Image Block","summary":"An image referenced by an ipfs:// link, with a caption in the text field and an optional display width."},"block/math":{"name":"Math Block","summary":"A block of LaTeX math, stored as text and rendered with KaTeX."},"block/node":{"name":"Block Node","summary":"One node of a content tree: a block plus its ordered child nodes, recursively, which is how documents and comments nest content."},"block/nostr":{"name":"Nostr Block","summary":"An embed of a Nostr event by nostr: URL."},"block/paragraph":{"name":"Paragraph Block","summary":"The default block: a paragraph of text with inline annotations; inside a table row it is a cell and carries the column id."},"block/query":{"name":"Query Block","summary":"A block that embeds a live query: the matching documents render in place as cards, a list or a table."},"block/table-column":{"name":"Table Column Block","summary":"One column of a Table block: a childless marker whose id cells reference and whose sibling order is the display order."},"block/table-row":{"name":"Table Row Block","summary":"One row of a Table block: its children are Paragraph cells, each naming its column with a columnId attribute."},"block/table":{"name":"Table Block","summary":"The container of a table: its children are TableColumn markers followed by TableRow blocks whose Paragraph cells carry a columnId."},"block/video":{"name":"Video Block","summary":"A video referenced by an ipfs:// file or a supported web video URL, with playback attributes."},"block/web-embed":{"name":"Web Embed Block","summary":"An embed of an external web page or post by https:// URL."},"boolean":{"name":"Boolean","summary":"A true or false value."},"bytes":{"name":"Bytes","summary":"Raw binary data (a byte string)."},"capability":{"name":"Capability","summary":"A signed grant from a space owner to another key: a role (WRITER or AGENT), an optional path scope, and nothing that expires or revokes it."},"change":{"name":"Change","summary":"A signed delta on a document that links the changes it depends on into a causal graph and carries the operations that mutate the document's content and metadata."},"change/body":{"name":"Change Body","summary":"The operations payload of a Change, an ordered list of ops plus an advisory count of the logical operations they represent."},"change/op":{"name":"Operation","summary":"One step inside a Change body, a map tagged by type that sets metadata, replaces a block, moves blocks, or deletes blocks, and the page explains how each op mutates the document."},"change/op/delete-blocks":{"name":"DeleteBlocks Op","summary":"The operation that removes blocks from the visible tree by moving them to the trash parent, from which a later move can restore them."},"change/op/move-blocks":{"name":"MoveBlocks Op","summary":"The operation that places a contiguous run of blocks under a parent after a reference position, using RGA op ids so concurrent moves converge and the latest move of a block wins."},"change/op/replace-block":{"name":"ReplaceBlock Op","summary":"The operation that sets the full state of one block, its id, type, text, link, annotations and attributes, where the newest replacement by op id wins."},"change/op/set-attributes":{"name":"SetAttributes Op","summary":"The operation that sets document metadata by key path, where each path is a last-writer-wins register and a nested write prunes older values above and below it."},"change/op/set-key":{"name":"SetKey Op","summary":"The deprecated flat form of SetAttributes that sets a single top-level metadata key, still accepted so old Changes replay."},"cid":{"name":"CID","summary":"A content identifier, the self-describing hash that names a blob by its bytes, written in Hypermedia as CIDv1 with the dag-cbor codec and either a SHA-256 or a BLAKE2b-256 multihash."},"comment":{"name":"Comment","summary":"A signed comment on a document version, threaded through threadRoot and replyParent, with a body that is a tree of comment blocks."},"contact":{"name":"Contact","summary":"A public address-book entry: one account's name for another account, with flags that say whether it joined that account's site or follows its profile."},"contact/subscribe":{"name":"Contact Subscription","summary":"The two follow flags on a contact: site means the account joined the subject's site, profile means it follows the subject as a person."},"date-time":{"name":"Date-Time","summary":"An instant held as an RFC 3339 string such as `2026-08-26T14:30:00Z`, with `format: date-time` so editors show a date-and-time picker."},"date":{"name":"Date","summary":"A calendar date held as an ISO 8601 `YYYY-MM-DD` string, with `format: date` so editors show a date picker and validators can check the shape."},"document":{"name":"Document","summary":"The read model of a Hypermedia document, the metadata and block tree that result from replaying its Changes, and the base every typed document's attributes are folded into."},"example/address":{"name":"Example: Address","summary":"A postal address: street and city (required) plus an optional postal code."},"example/admin":{"name":"Example: Admin","summary":"An employee, extended with a map of boolean permission flags."},"example/app-block":{"name":"Example: App Block (Extended Core)","summary":"How a third party extends the block model: a strict union of Hypermedia’s core blocks plus the app’s own Poll block, rejecting block types it does not know."},"example/article":{"name":"Example: Article","summary":"A published article: status, author, tags, a bytes body, cover image, comments, and metadata."},"example/blob":{"name":"Example: Blob","summary":"A binary payload tagged with a MIME type and optional size."},"example/character-doc":{"name":"Character","summary":"A world-builder page type for a character, whose attributes require a birth date and a role and link to a home place, a faction, a portrait, and a stats object."},"example/comment":{"name":"Example: Comment","summary":"A comment with an author and replies, which are themselves comments."},"example/constrained":{"name":"Example: Constrained Record","summary":"A record that shows the value constraints: string length and pattern, numeric bounds, and list size."},"example/counts":{"name":"Example: Counts","summary":"A map from string keys to integers: Map<Integer>."},"example/document":{"name":"Example: Document","summary":"A document with a title, an author, a body, and a link to a previous document."},"example/employee":{"name":"Example: Employee","summary":"A person, extended with an employee id and department."},"example/entry":{"name":"Example: Filesystem Entry","summary":"Either a folder or a file, as a union."},"example/event-doc":{"name":"Event","summary":"A world-builder page type for something that happened, whose attributes require a date and link the event to a place and a protagonist character."},"example/faction-doc":{"name":"Faction","summary":"A world-builder page type for a faction, order, house, or guild, whose attributes require a founding date and link to its seat, its leader, and a banner."},"example/file":{"name":"Example: File","summary":"A file with a name and a link to its parent folder."},"example/folder":{"name":"Example: Folder","summary":"A folder with a name and links to its files and subfolders."},"example/geo":{"name":"Example: Geo Point","summary":"A latitude and longitude coordinate with an optional altitude."},"example/json":{"name":"Example: JSON Value","summary":"A recursive JSON value: null, boolean, number, string, list, or map."},"example/matrix":{"name":"Example: Matrix","summary":"A list of lists of integers: List<List<Integer>>."},"example/metadata":{"name":"Example: Metadata","summary":"Arbitrary string-to-string metadata: Map<String>."},"example/myapp-change":{"name":"Example: MyApp Change","summary":"A Change instantiated with the app’s block type, so its ReplaceBlock ops are validated strictly against core blocks plus Poll instead of the open default."},"example/person-doc":{"name":"Example: Person Document","summary":"A document type for a person: an attributes schema requiring a surname with an optional given name, bound per page or to every child of a folder."},"example/person":{"name":"Example: Person","summary":"A person with a name, age, active flag, home address, and nicknames."},"example/place-doc":{"name":"Place","summary":"A world-builder page type for a place, whose attributes require a kind and may add a founding date, a parent region, and a coordinates object."},"example/poll-block":{"name":"Example: Poll Block (Custom)","summary":"An example third-party block type: a poll with a question and options. It extends the shared block base, exactly like a core block."},"example/registry":{"name":"Example: Registry","summary":"A map from ids to person links: Map<Link<Person>>."},"example/stats":{"name":"Character Stats","summary":"A character’s stats object, stored as its own DAG-CBOR blob linked by `ipfs://` so it can hold the integers and enums document metadata cannot."},"example/status":{"name":"Example: Status","summary":"A publication status: draft, published, or archived."},"example/tags":{"name":"Example: Tags","summary":"A list of string tags: List<String>."},"example/tree":{"name":"Example: Tree","summary":"A node holding an integer value and links to child nodes."},"example/value":{"name":"Example: Value","summary":"A primitive value: string, integer, boolean, or null."},"example/world-doc":{"name":"World","summary":"A world-builder page type for the root of a fictional world, whose children hold the type definitions and the folders of characters, places, factions, and events."},"float":{"name":"Float","summary":"A floating-point number."},"hm-url":{"name":"Resource URL","summary":"A reference to a Hypermedia document held as an `hm://` URL string, which editors render as a searchable pill showing the target’s title."},"integer":{"name":"Integer","summary":"A whole number, which DAG-CBOR encodes distinctly from floats."},"ipfs-url":{"name":"IPFS URL","summary":"A reference to a content-addressed object held as an `ipfs://<cid>` string, which editors render as a file pill you can open, upload to, or paste into."},"key-value":{"name":"Key/Value","summary":"One attribute assignment in a SetAttributes op: a key path (a list of segments) and a scalar value."},"link":{"name":"Link","summary":"The IPLD link kind, a CID inside a value that points at another block by its content, encoded as CBOR tag 42 and spelled with a slash key in DAG-JSON."},"list":{"name":"List","summary":"An ordered sequence, which is List<Any> until it is parameterized with items."},"map":{"name":"Map","summary":"A map of string keys to values of one type (Map<Any> until `values` constrains it); use a struct when the field names are known."},"metadata":{"name":"Document Metadata","summary":"The attributes of a document, merged from its Changes: the keys Seed understands, the three schema-binding keys, and any custom keys a typed document adds."},"metadata/navigation-item":{"name":"Navigation item","summary":"One entry of a site's navigation menu: a Link block with display text and a link, stored as a child of the detached navigation block."},"none":{"name":"None","summary":"The bottom type, which accepts no values and is defined as an empty union."},"null":{"name":"Null","summary":"The null value."},"principal":{"name":"Principal","summary":"A public key that identifies an account or space, stored in blobs as the raw bytes of a multicodec prefix plus the key and shown to people as a base58 string starting with z6Mk."},"profile":{"name":"Profile","summary":"A snapshot blob giving an account its display name, avatar and description, or an alias that redirects one key to another; readers merge every profile for an account field by field."},"query":{"name":"Query","summary":"A live document query: which spaces and paths to include, how to sort, and an optional limit; the payload of a Query block and of the Query request."},"query/inclusion":{"name":"Query Inclusion","summary":"One source a query pulls documents from: a space, an optional path prefix inside it, and whether to list direct children or all descendants."},"query/sort":{"name":"Query Sort","summary":"One sort term for query results, optionally reversed; the app writes lowercase terms and normalizes the older capitalized spellings on read."},"query/style":{"name":"Query Style","summary":"How a Query block presents its results: a card grid, a compact list, or a table."},"query/table-config":{"name":"Query Table Config","summary":"The persisted settings of a Query block's table view: which columns are visible and how wide they are."},"ref":{"name":"Ref","summary":"A signed claim, like a Git ref, that a path in a space points at the current head Changes of a document, or that the path is deleted or redirects elsewhere."},"ref/redirect-target":{"name":"Redirect Target","summary":"The destination carried by a redirect Ref, a space and path to send readers to, with a republish flag that keeps the content showing under the old address."},"role":{"name":"Role","summary":"The kind of capability being granted: WRITER may publish under a path, AGENT may act as the issuing account; no other role exists in data."},"rpc/account-contacts":{"name":"RPC: AccountContacts","summary":"Returns the contact records an account has written, given that account’s uid."},"rpc/account":{"name":"RPC: Account","summary":"Resolves an account uid to its metadata payload, or to an explicit not-found result."},"rpc/comment":{"name":"RPC: Comment","summary":"Returns one comment as the API read model, given its id (uid/tsid) or a version CID."},"rpc/discovery-status":{"name":"RPC: DiscoveryStatus","summary":"Reports whether a background discovery task for a resource (uid, path, optional version) is pending, found, or failed."},"rpc/get-cid":{"name":"RPC: GetCID","summary":"Fetches a raw IPFS block by CID and returns it decoded as a DAG-JSON value."},"rpc/get-comment-reply-count":{"name":"RPC: GetCommentReplyCount","summary":"Returns the number of replies under a comment, given the comment id."},"rpc/get-domain":{"name":"RPC: GetDomain","summary":"Returns the daemon’s registration and health view of one site domain, optionally forcing a fresh check."},"rpc/interaction-summary":{"name":"RPC: InteractionSummary","summary":"Returns a document’s aggregate citation, comment, change, child, and author counts with per-block breakdowns, given its id."},"rpc/list-accounts":{"name":"RPC: ListAccounts","summary":"Returns every account the daemon knows as a list of metadata payloads; it takes no meaningful input."},"rpc/list-capabilities":{"name":"RPC: ListCapabilities","summary":"Returns the raw capabilities granted on a target document, given its id."},"rpc/list-changes":{"name":"RPC: ListChanges","summary":"Returns a document’s change history as raw change records plus its latest version, given the target id."},"rpc/list-citations":{"name":"RPC: ListCitations","summary":"Returns the raw citations that point at a target resource, given its id."},"rpc/list-comment-versions":{"name":"RPC: ListCommentVersions","summary":"Returns every stored version of a comment, given its id."},"rpc/list-comments-by-author":{"name":"RPC: ListCommentsByAuthor","summary":"Returns the comments an author has written, with the author metadata payloads, given the author’s id."},"rpc/list-comments-by-reference":{"name":"RPC: ListCommentsByReference","summary":"Returns the comments that reference a specific block, given a target id that carries the block reference."},"rpc/list-comments":{"name":"RPC: ListComments","summary":"Returns all comments on a target document, with the metadata payloads of their authors."},"rpc/list-discussions":{"name":"RPC: ListDiscussions","summary":"Returns a document’s comments grouped into threads, their authors’ metadata, and threads from other documents that cite it, optionally focused on one comment."},"rpc/list-document-collaborators":{"name":"RPC: ListDocumentCollaborators","summary":"Returns a document’s collaboration picture (publisher, inherited and direct capabilities, effective members), given its id."},"rpc/list-domains":{"name":"RPC: ListDomains","summary":"Returns every site domain the daemon knows, each with its registration and health info."},"rpc/list-events":{"name":"RPC: ListEvents","summary":"Pages through the activity feed as activity events, filtered by author, event type, or resource, with a token for the next page."},"rpc/list-refs":{"name":"RPC: ListRefs","summary":"Returns every Ref published at a document path, newest generation first, given the target id."},"rpc/method":{"name":"RPC","summary":"The union of every read-only method of the Seed API, each variant pinning a method key and typing its input and output."},"rpc/query-block":{"name":"RPC: QueryBlock","summary":"Runs a Query block’s query and returns the results plus the per-item interaction summaries and author metadata its rendering needs, or null."},"rpc/query":{"name":"RPC: Query","summary":"Runs a document query (the same shape a Query block embeds) and returns the matching documents as a query result, or null."},"rpc/resource-metadata":{"name":"RPC: ResourceMetadata","summary":"Returns only the metadata payload of a resource, given its parsed id."},"rpc/resource":{"name":"RPC: Resource","summary":"Fetches a resource by parsed id and returns whichever state it is in: document, comment, redirect, not found, tombstone, or error."},"rpc/search":{"name":"RPC: Search","summary":"Searches the network for documents, contacts, and comments matching a query string, with optional account, type, and paging filters."},"rpc/subject-contacts":{"name":"RPC: SubjectContacts","summary":"Returns the contact records that name a subject account, given the subject’s uid."},"rpc/type/account-result":{"name":"Account Result","summary":"The result of resolving an account: its metadata payload, or an explicit not-found."},"rpc/type/accounts-metadata":{"name":"Accounts Metadata","summary":"A map from account uid to resolved metadata payload, sent alongside listings so clients can render authors without extra requests."},"rpc/type/activity-event":{"name":"Activity Event","summary":"One event of the activity feed, currently an open map because the event union is not yet pinned down schema-side."},"rpc/type/activity-summary":{"name":"Activity Summary","summary":"The latest-activity digest carried on document listings: the newest comment or change and the unread state."},"rpc/type/block-range":{"name":"Block Range","summary":"A selection within a block, either as character offsets (start and end) or as the whole block expanded."},"rpc/type/breadcrumb":{"name":"Breadcrumb","summary":"One ancestor entry of a document’s path, resolved to a display name."},"rpc/type/capability":{"name":"Capability (Payload)","summary":"A capability as the API returns it: who was granted which role on which grant id."},"rpc/type/citation":{"name":"Citation","summary":"One mention of a target resource from elsewhere on the network: the citing document or comment, whether it pinned an exact version, and the fragment it points at."},"rpc/type/collaborators-payload":{"name":"Collaborators Payload","summary":"A document’s collaboration picture: the publisher, inherited and directly granted capabilities, effective members, and their metadata."},"rpc/type/comment-group":{"name":"Comment Group","summary":"A thread of comments grouped for display, with a count of elided replies."},"rpc/type/comment-list":{"name":"Comment List","summary":"A list of comments plus the metadata payloads of every author involved."},"rpc/type/comment":{"name":"Comment (Payload)","summary":"A comment as the API returns it: the signed comment’s content plus derived fields such as stable id, version CID, thread links, timestamps, and visibility."},"rpc/type/contact-record":{"name":"Contact Record","summary":"A contact as the API returns it: who named whom what, signed by which key, with timestamps and subscription preferences."},"rpc/type/discovery-status":{"name":"Discovery Status","summary":"The state of a background discovery task for a resource: pending, found with the resolved version, or failed with the error."},"rpc/type/document-info":{"name":"Document Info","summary":"One document in a listing: identity, authorship, timestamps, breadcrumbs, and activity summary, without the full content."},"rpc/type/document":{"name":"Document (Payload)","summary":"A document as the API returns it: the signed document’s metadata and content plus derived fields such as resolved version, authors, timestamps, and visibility."},"rpc/type/domain-info":{"name":"Domain Info","summary":"The daemon’s view of a site domain: registration, gateway status, and health-check results."},"rpc/type/external-comment-group":{"name":"External Comment Group","summary":"A comment thread from another document that cites this one, with its target’s metadata payload."},"rpc/type/id":{"name":"Parsed ID","summary":"A parsed hm:// identifier as clients pass it around (account uid, path segments, pinned version, block reference, origin hints), with null for whatever the URL does not carry."},"rpc/type/interaction-summary":{"name":"Interaction Summary","summary":"Aggregate interaction counts for a document (citations, comments, changes, child documents, distinct authors) plus per-block citation and comment counts."},"rpc/type/metadata-payload":{"name":"Metadata Payload","summary":"A resource id with its resolved metadata, or null when the document has none."},"rpc/type/parsed-fragment":{"name":"Parsed Fragment","summary":"A parsed URL fragment addressing a block and, optionally, a range inside it."},"rpc/type/query-block-item-summary":{"name":"Query Block Item Summary","summary":"The per-result interaction counts a Query block shows on its cards: comments, children, and author uids."},"rpc/type/query-block-payload":{"name":"Query Block Payload","summary":"Everything a rendered Query block needs: the results plus per-item interaction summaries and author metadata."},"rpc/type/query-result":{"name":"Query Result","summary":"The documents a query matched, listed under the queried id together with the mode (children or all descendants) that was used."},"rpc/type/raw-capability":{"name":"Raw Capability","summary":"A capability as indexed, in raw wire form with every field an optional string."},"rpc/type/raw-citation":{"name":"Raw Citation","summary":"A citation in raw indexed form, before client-side resolution into a citation read model."},"rpc/type/raw-document-change":{"name":"Raw Document Change","summary":"One change of a document’s history in raw listing form: CID, author, dependency edges, and time."},"rpc/type/raw-ref":{"name":"Raw Ref","summary":"A Ref as indexed, in raw wire form, pointing at a version, a redirect or a tombstone."},"rpc/type/redirect-info":{"name":"Redirect Info","summary":"Marks a listed document as a redirect to another target, optionally republishing its content in place."},"rpc/type/resource-comment":{"name":"Resource: Comment","summary":"A resolved resource that is a comment: the parsed id plus the comment read model."},"rpc/type/resource-document":{"name":"Resource: Document","summary":"A resolved resource that is a document: the parsed id plus the document read model."},"rpc/type/resource-error":{"name":"Resource: Error","summary":"A resource that failed to load, carrying its id and the error message."},"rpc/type/resource-not-found":{"name":"Resource: Not Found","summary":"A resource id that resolved to nothing."},"rpc/type/resource-redirect":{"name":"Resource: Redirect","summary":"A resource that redirects to another id, optionally republishing its content in place."},"rpc/type/resource-tombstone":{"name":"Resource: Tombstone","summary":"A resource that was deleted by a tombstone ref."},"rpc/type/resource":{"name":"Resource","summary":"The union of every state a fetched resource can be in: document, comment, redirect, not found, tombstone, or error."},"rpc/type/search-result-item":{"name":"Search Result Item","summary":"One hit of a network search: the matched id with its title, icon, and breadcrumb parent names, and what kind of entity matched."},"rpc/type/search-results":{"name":"Search Results","summary":"A page of search results with the query echoed back and a token for the next page."},"rpc/type/site-member":{"name":"Site Member","summary":"One member of a site with their effective role: owner, writer, or member."},"schema":{"name":"Schema","summary":"The meta-schema, which is the union of every shape a schema can take and a valid instance of itself, with a guide to schemas in the Seed app and an index of the reference pages."},"schema/anyof":{"name":"Union schema","summary":"The variant for a union, which accepts a value that matches any one of the schemas listed under anyOf."},"schema/include-schema":{"name":"Reference Schema","summary":"The variant for a reference, which is a bare include or, when it carries refinements, an extension."},"schema/link-schema":{"name":"Link schema","summary":"The variant for a link (a CID), which can name the type it expects to point at."},"schema/list-schema":{"name":"List schema","summary":"The variant for a list value, where items types the elements."},"schema/literal-schema":{"name":"Literal Schema","summary":"The variant for a literal, which is a schema that accepts exactly one value and can describe what that value means."},"schema/map-schema":{"name":"Map schema","summary":"The variant for a map whose keys are arbitrary and whose values all match the one schema under values, while known fields belong in a struct schema."},"schema/property":{"name":"Property","summary":"One field of a struct, holding its value schema, whether a value must include it, and a description of what it is for."},"schema/scalar-schema":{"name":"Scalar schema","summary":"The variant for a null, boolean, integer, float, string or bytes value, optionally narrowed by value constraints."},"schema/struct-schema":{"name":"Struct schema","summary":"The variant for a struct, with known fields under properties and optionally extra keys of one type under values."},"schema/var-schema":{"name":"Variable Schema","summary":"A type-variable reference, written { \"var\": \"<name>\" }, that matches whatever a generic's parameter is bound to."},"signature":{"name":"Signature","summary":"The 64 raw bytes of an Ed25519 or P-256 signature over a blob's canonical CBOR encoding taken with this very field set to zeros."},"string":{"name":"String","summary":"UTF-8 text."},"struct":{"name":"Struct","summary":"A map with known, named fields, the type behind every record-like value from an address to a signed Change."},"timestamp":{"name":"Timestamp","summary":"A point in time as an integer of Unix milliseconds, issued by a causal clock when a blob is signed and never checked against wall-clock time on arrival."},"url":{"name":"URL","summary":"A string holding a URL of any scheme, which `format: url` tells an editor to render as a link and to validate as one."},"value":{"name":"Value","summary":"A metadata or attribute value: a string, an integer, a boolean, or null."},"visibility":{"name":"Visibility","summary":"The visibility of a Ref or Comment, empty for public and \"Private\" for private, from which every Change and file it links inherits its own visibility."}}

